import os
os.chdir('/work/accept-t7')

controlDict = """FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object controlDict;
}
application     buoyantSimpleFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
"""
with open("system/controlDict", "w") as f:
    f.write(controlDict)

fvSchemes = """FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSchemes;
}
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
"""
with open("system/fvSchemes", "w") as f:
    f.write(fvSchemes)

fvSolution = """FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSolution;
}
solvers
{
}
"""
with open("system/fvSolution", "w") as f:
    f.write(fvSolution)

# ---- topoSetDict: two cellZones aligned to the grid ----
topoSetDict = f"""FoamFile
{{
    version 2.0;
    format ascii;
    class dictionary;
    object topoSetDict;
}}

actions
(
    {{
        name    heater;
        type    cellZoneSet;
        action  new;
        source  boxToCell;
        box     ({heater_x0} {heater_y0} {heater_z0}) ({heater_x1} {heater_y1} {heater_z1});
    }}
    {{
        name    cooler;
        type    cellZoneSet;
        action  new;
        source  boxToCell;
        box     ({cooler_x0} {cooler_y0} {cooler_z0}) ({cooler_x1} {cooler_y1} {cooler_z1});
    }}
);
"""
with open("system/topoSetDict", "w") as f:
    f.write(topoSetDict)

print("wrote system/controlDict, fvSchemes, fvSolution, topoSetDict")
